177: function note(context, frequency, delay, duration, type = "sine", volume = 0.05) {
178:   const start = context.currentTime + delay;
179:   const oscillator = context.createOscillator();
180:   const gain = context.createGain();
181:   oscillator.type = type;
182:   oscillator.frequency.setValueAtTime(frequency, start);
183:   gain.gain.setValueAtTime(0.0001, start);
184:   gain.gain.exponentialRampToValueAtTime(volume, start + 0.012);
185:   gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
186:   oscillator.connect(gain);
187:   gain.connect(context.destination);
188:   oscillator.start(start);
189:   oscillator.stop(start + duration + 0.03);
190: }
