243: function burstConfetti(count = 85, accent = "#f6ff5c") {
244:   if (prefersReducedMotion()) return;
245:   const palette = [accent, "#f6ff5c", "#ff5ca8", "#67e8f9", "#ffffff"];
246:   const originX = confetti.width / 2;
247:   const originY = confetti.height * 0.42;
248:   if (confetti.particles.length > 260) {
249:     confetti.particles.splice(0, confetti.particles.length - 260);
250:   }
251:   for (let index = 0; index < count; index += 1) {
252:     const angle = -Math.PI / 2 + (Math.random() - 0.5) * 2.1;
253:     const speed = 260 + Math.random() * 620;
254:     confetti.particles.push({
255:       x: originX + (Math.random() - 0.5) * 120,
256:       y: originY + (Math.random() - 0.5) * 40,
257:       vx: Math.cos(angle) * speed,
258:       vy: Math.sin(angle) * speed,
259:       size: 4 + Math.random() * 7,
260:       color: palette[Math.floor(Math.random() * palette.length)],
261:       rotation: Math.random() * Math.PI,
262:       spin: (Math.random() - 0.5) * 12,
263:       life: 1.4 + Math.random() * 0.8,
264:       age: 0,
265:       round: Math.random() > 0.55,
266:     });
267:   }
268:   if (!confetti.frame) {
269:     confetti.last = performance.now();
270:     confetti.frame = requestAnimationFrame(stepConfetti);
271:   }
272: }
