274: function stepConfetti(timestamp) {
275:   const delta = Math.min(0.04, (timestamp - confetti.last) / 1000);
276:   confetti.last = timestamp;
277:   fxContext.clearRect(0, 0, confetti.width, confetti.height);
278:   confetti.particles = confetti.particles.filter((particle) => {
279:     particle.age += delta;
280:     if (particle.age >= particle.life) return false;
281:     particle.vy += 780 * delta;
282:     particle.vx *= 0.988;
283:     particle.vy *= 0.992;
284:     particle.x += particle.vx * delta;
285:     particle.y += particle.vy * delta;
286:     particle.rotation += particle.spin * delta;
287:     const fade = Math.max(0, 1 - Math.max(0, (particle.age - particle.life * 0.62) / (particle.life * 0.38)));
288:     fxContext.save();
289:     fxContext.globalAlpha = fade;
290:     fxContext.translate(particle.x, particle.y);
291:     fxContext.rotate(particle.rotation);
292:     fxContext.fillStyle = particle.color;
293:     if (particle.round) {
294:       fxContext.beginPath();
295:       fxContext.arc(0, 0, particle.size / 2, 0, Math.PI * 2);
296:       fxContext.fill();
297:     } else {
298:       fxContext.fillRect(-particle.size / 2, -particle.size / 4, particle.size, particle.size / 2);
299:     }
300:     fxContext.restore();
301:     return true;
302:   });
303:   if (confetti.particles.length) {
304:     confetti.frame = requestAnimationFrame(stepConfetti);
305:   } else {
306:     confetti.frame = 0;
307:     fxContext.clearRect(0, 0, confetti.width, confetti.height);
308:   }
309: }
