455:     done: 0,
456:     chicken: 0,
457:     skip: 0,
458:     streak: 0,
459:     bestStreak: 0,
460:     cats: {},
461:   }));
462: 
463:   if (config.mode === "group" && players.length < 2) {
464:     showToast("Group mode needs at least two players.");
465:     return;
466:   }
467: 
468:   const deck = shuffle(daresFor({
469:     categories,
470:     maxLevel: config.level || 3,
471:     playerCount: players.length,
472:   }));
473: 
474:   if (!deck.length) {
475:     showToast("No dares match that setup. Add a category or raise the intensity.");
476:     return;
477:   }
478: 
479:   const wantedTurns = config.mode === "solo"
480:     ? Number(config.length) || 10
481:     : players.length * (Number(config.turns) || 1);
482:   const totalTurns = Math.min(wantedTurns, deck.length);
483: 
484:   stopTimer();
485:   game = {
486:     config: {
487:       mode: config.mode,
488:       length: Number(config.length) || 10,
489:       turns: Number(config.turns) || 1,
490:       level: Number(config.level) || 3,
491:       categories: [...categories],
492:       players: players.map((player) => ({ name: player.name })),
493:     },
494:     players,
495:     deck,
496:     deckSize: deck.length,
497:     totalTurns,
498:     wantedTurns,
499:     turn: 1,
500:     drawn: 0,
501:     activeIndex: 0,
502:     phase: "deal",
503:     currentDare: null,
504:     result: null,
505:     timer: { total: 0, remaining: 0, started: false, endAt: 0 },
506:     finished: false,
507:     statsRecorded: false,
508:   };
509: 
510:   els.resultStamp.hidden = true;
511:   els.resultStamp.className = "result-stamp";
512:   els.resultStamp.innerHTML = "";
513:   els.gameCard.classList.remove("is-success", "is-fail");
514:   showScreen("game");
515:   dealNext();
516: 
517:   if (totalTurns < wantedTurns) {
518:     showToast(`Only ${totalTurns} dares match those filters — the run was shortened.`);
519:   }
520: }
521: 
522: function dealNext() {
523:   if (!game) return;
524:   if (game.turn > game.totalTurns || game.deck.length === 0) {
525:     endGame();
526:     return;
527:   }
528: 
529:   game.activeIndex = game.config.mode === "group"
530:     ? (game.turn - 1) % game.players.length
531:     : 0;
532:   game.currentDare = game.deck.pop();
533:   game.drawn += 1;
534:   game.phase = "deal";
535:   game.result = null;
536:   game.timer = {
537:     total: game.currentDare.secs || 0,
538:     remaining: game.currentDare.secs || 0,
539:     started: false,
540:     endAt: 0,
541:   };
542: 
543:   renderGame();
544:   animateCard();
545:   playSound("draw");
546: }
