548: function animateCard() {
549:   els.gameCard.classList.remove("is-dealing");
550:   void els.gameCard.offsetWidth;
551:   els.gameCard.classList.add("is-dealing");
552:   window.setTimeout(() => els.gameCard.classList.remove("is-dealing"), 620);
553: }
