559: function renderGame() {
560:   if (!game || !game.currentDare) return;
561:   const dare = game.currentDare;
562:   const category = CATEGORIES[dare.cat];
563:   const player = activePlayer();
564:   const round = Math.floor((game.turn - 1) / game.players.length) + 1;
565: 
566:   els.gameCard.style.setProperty("--cat", category.color);
567:   els.cardCategory.textContent = `${category.icon} ${category.name}`;
568:   els.cardLevel.textContent = `LEVEL ${dare.lvl} · ${LEVEL_LABEL[dare.lvl]}`;
569:   els.cardIcon.textContent = category.icon;
