572:   els.cardIndex.textContent = `#${String(game.drawn).padStart(3, "0")} / ${game.deckSize}`;
573:   els.announcer.textContent = `${category.name} dare, level ${dare.lvl}. ${dare.text}`;
574:   els.gameCard.classList.remove("is-success", "is-fail");
575:   els.resultStamp.hidden = true;
576:   els.resultStamp.className = "result-stamp";
577:   els.resultStamp.innerHTML = "";
