579:   if (game.config.mode === "group") {
580:     els.turnKicker.textContent = `ROUND ${round} OF ${game.config.turns}`;
581:     els.turnLabel.textContent = player.name;
582:     els.turnAvatar.textContent = initials(player.name);
583:     els.turnAvatar.style.setProperty("--dot", player.color);
