655: function setTimerUi(remaining, total) {
656:   if (total <= 0) {
657:     els.timerRing.style.strokeDashoffset = "0";
658:     els.timerText.textContent = "∞";
659:     els.timerRingWrap.classList.add("is-off");
660:     els.timerRingWrap.classList.remove("is-urgent");
661:     return;
662:   }
663:   const ratio = Math.max(0, Math.min(1, remaining / total));
664:   const circumference = 169.65;
665:   els.timerRing.style.strokeDashoffset = String(circumference * (1 - ratio));
666:   els.timerText.textContent = formatTime(remaining);
667:   const urgent = remaining > 0 && remaining <= 5 && game && game.phase === "running";
668:   els.timerRingWrap.classList.toggle("is-urgent", urgent);
669: }
