671: /* ── Timer ─────────────────────────────────────────────────────────── */
672: 
673: function startTimer() {
674:   if (!game || !game.currentDare || game.currentDare.secs <= 0) return;
675:   if (game.phase === "running") return;
676:   const remaining = game.timer.remaining > 0 ? game.timer.remaining : game.timer.total;
677:   game.timer.remaining = remaining;
678:   game.timer.endAt = performance.now() + remaining * 1000;
679:   game.timer.started = true;
680:   game.phase = "running";
681:   lastTickSecond = null;
682:   window.clearInterval(timerId);
683:   timerId = window.setInterval(tickTimer, 80);
684:   setTimerStatus("Live", "is-live");
685:   els.cardHint.textContent = "Timer running. Breathe.";
686:   renderControls();
687:   playSound("start");
688: }
689: 
690: function pauseTimer() {
691:   if (!game || game.phase !== "running") return;
692:   game.timer.remaining = Math.max(0, (game.timer.endAt - performance.now()) / 1000);
693:   window.clearInterval(timerId);
694:   timerId = null;
695:   game.phase = "paused";
696:   setTimerUi(game.timer.remaining, game.timer.total);
697:   setTimerStatus("Paused", "is-paused");
698:   els.cardHint.textContent = "Paused. Take your time.";
699:   renderControls();
700:   playSound("pause");
701: }
702: 
703: function resumeTimer() {
704:   if (!game || game.phase !== "paused") return;
705:   startTimer();
706: }
707: 
708: function stopTimer() {
709:   window.clearInterval(timerId);
710:   timerId = null;
711: }
712: 
713: function tickTimer() {
714:   if (!game || game.phase !== "running") return;
715:   const remaining = Math.max(0, (game.timer.endAt - performance.now()) / 1000);
716:   game.timer.remaining = remaining;
717:   setTimerUi(remaining, game.timer.total);
718: 
719:   const second = Math.ceil(remaining);
720:   if (second > 0 && second <= 3 && second !== lastTickSecond) {
721:     lastTickSecond = second;
722:     playSound("tick");
723:   }
724: 
725:   if (remaining <= 0) {
726:     stopTimer();
727:     game.phase = "timeup";
728:     game.timer.remaining = 0;
729:     setTimerUi(0, game.timer.total);
730:     setTimerStatus("Time!", "is-done");
731:     els.cardHint.textContent = "Time's up. Well? Did you hold it?";
732:     renderControls();
733:     playSound("timeup");
734:   }
735: }
