743: function nextTurnLabel() {
744:   if (!game) return "Next";
745:   const nextTurn = game.turn + 1;
746:   if (nextTurn > game.totalTurns || game.deck.length === 0) return "See results";
747:   if (game.config.mode === "group") {
748:     const nextPlayer = game.players[(nextTurn - 1) % game.players.length];
749:     return `Next: ${nextPlayer.name}`;
