758: 
759:   if (game.phase === "result") {
760:     markup = controlsButton("next", `${esc(nextTurnLabel())} →`, "primary-button wide");
761:   } else if (game.phase === "running") {
762:     markup = [
763:       controlsButton("timer", "Pause", "primary-button"),
764:       controlsButton("done", "Done", "secondary-button"),
765:       controlsButton("chicken", "Chicken out", "ghost-button"),
766:       controlsButton("skip", "Skip this dare (safe word)", "ghost-button skip-button"),
767:     ].join("");
768:   } else if (game.phase === "paused") {
769:     markup = [
770:       controlsButton("timer", "Resume", "primary-button"),
771:       controlsButton("done", "Done", "secondary-button"),
772:       controlsButton("chicken", "Chicken out", "ghost-button"),
773:       controlsButton("skip", "Skip this dare (safe word)", "ghost-button skip-button"),
774:     ].join("");
775:   } else if (game.phase === "timeup") {
776:     markup = [
777:       controlsButton("done", "Done", "primary-button"),
778:       controlsButton("chicken", "Chicken out", "secondary-button"),
779:       controlsButton("skip", "Skip this dare (safe word)", "ghost-button skip-button"),
780:     ].join("");
781:   } else {
782:     markup = [
783:       timed ? controlsButton("timer", "Start timer", "primary-button") : "",
784:       controlsButton("done", timed ? "Done" : "Done — I did it", timed ? "secondary-button" : "primary-button"),
785:       controlsButton("chicken", "Chicken out", timed ? "ghost-button" : "secondary-button"),
786:       controlsButton("skip", "Skip this dare (safe word)", "ghost-button skip-button"),
787:     ].join("");
788:   }
789: 
790:   els.controls.innerHTML = markup;
