793: /* ── Resolve a card ────────────────────────────────────────────────── */
794: 
795: function resolveCard(kind) {
796:   if (!game || game.phase === "result") return;
797:   const dare = game.currentDare;
798:   const player = activePlayer();
799:   if (!dare || !player) return;
800: 
801:   stopTimer();
802:   const previousScore = player.score;
803:   let points = 0;
804:   let bonus = 0;
805: 
806:   if (kind === "done") {
807:     bonus = game.timer.started && game.timer.total > 0 && game.timer.remaining > game.timer.total * 0.35 ? 5 : 0;
808:     points = 10 + dare.lvl * 5 + bonus;
809:     player.score += points;
810:     player.done += 1;
811:     player.streak += 1;
812:     player.bestStreak = Math.max(player.bestStreak, player.streak);
813:     player.cats[dare.cat] = (player.cats[dare.cat] || 0) + 1;
814:   } else if (kind === "chicken") {
815:     player.chicken += 1;
816:     player.streak = 0;
817:   } else {
818:     player.skip += 1;
819:   }
820: 
821:   game.phase = "result";
822:   game.result = { kind, points, bonus, previousScore, playerName: player.name };
823:   renderResultUi(kind, points, bonus);
824:   els.announcer.textContent = kind === "done"
825:     ? `Nailed it. ${points} points for ${player.name}.`
826:     : kind === "chicken"
827:       ? `${player.name} chickened out. No points.`
828:       : `${player.name} used the safe word. Card skipped.`;
829:   setTimerStatus(kind === "done" ? "Done" : kind === "chicken" ? "Chicken" : "Skipped", "is-done");
830:   updateProgress();
831:   updateScore(kind === "done");
832:   updatePlayersStrip();
833:   renderControls();
834: 
835:   if (kind === "done") {
836:     const accent = CATEGORIES[dare.cat] ? CATEGORIES[dare.cat].color : "#f6ff5c";
837:     burstConfetti(90, accent);
838:     playSound("success");
839:   } else if (kind === "chicken") {
840:     playSound("fail");
841:   } else {
842:     playSound("skip");
843:   }
844: }
845: 
846: function renderResultUi(kind, points, bonus) {
847:   els.resultStamp.hidden = false;
848:   els.resultStamp.className = "result-stamp";
849:   els.gameCard.classList.remove("is-success", "is-fail");
850: 
851:   if (kind === "done") {
852:     els.gameCard.classList.add("is-success");
853:     els.resultStamp.innerHTML = `
854:       <strong>NAILED IT</strong>
855:       <span>+${points} PTS</span>
856:       <small>${bonus ? "Includes a +5 fast-finish bonus." : "One less card. One more story."}</small>
857:     `;
858:     els.cardHint.textContent = "Result locked in.";
859:   } else if (kind === "chicken") {
860:     els.gameCard.classList.add("is-fail");
861:     els.resultStamp.classList.add("is-fail");
862:     els.resultStamp.innerHTML = `
863:       <strong>CHICKENED OUT</strong>
864:       <span>0 PTS</span>
865:       <small>No shame. The card has left the deck.</small>
866:     `;
867:     els.cardHint.textContent = "Honesty counts.";
868:   } else {
869:     els.resultStamp.classList.add("is-skip");
870:     els.resultStamp.innerHTML = `
871:       <strong>SAFE WORD</strong>
872:       <span>SKIPPED</span>
873:       <small>No explanation needed. Moving on.</small>
874:     `;
875:     els.cardHint.textContent = "Skipped without drama.";
876:   }
877: }
878: 
879: function nextTurn() {
880:   if (!game) return;
881:   game.turn += 1;
882:   if (game.turn > game.totalTurns || game.deck.length === 0) {
883:     endGame();
884:     return;
885:   }
886:   dealNext();
887: }
