892: 
893: function loadStats() {
894:   const defaults = {
895:     games: 0,
896:     dares: 0,
897:     points: 0,
898:     bestScore: 0,
899:     bestStreak: 0,
900:   };
901:   return { ...defaults, ...readStore(STORAGE_STATS, defaults) };
902: }
903: 
904: function soloRank(ratio, played) {
905:   if (played === 0) return { title: "No Dares Taken", icon: "🫥" };
906:   if (ratio === 1) return { title: "Certified Menace", icon: "👑" };
907:   if (ratio >= 0.8) return { title: "Daredevil", icon: "🔥" };
908:   if (ratio >= 0.5) return { title: "Brave-ish", icon: "🫡" };
909:   if (ratio > 0) return { title: "Cardboard Hero", icon: "📦" };
910:   return { title: "Professional Spectator", icon: "🍿" };
911: }
912: 
913: function endGame() {
914:   if (!game || game.finished) return;
915:   game.finished = true;
916:   stopTimer();
917: 
918:   const players = game.players;
919:   const totalDone = players.reduce((sum, player) => sum + player.done, 0);
920:   const totalChicken = players.reduce((sum, player) => sum + player.chicken, 0);
921:   const totalSkip = players.reduce((sum, player) => sum + player.skip, 0);
922:   const played = totalDone + totalChicken + totalSkip;
923:   const totalScore = players.reduce((sum, player) => sum + player.score, 0);
924:   const bestStreak = Math.max(0, ...players.map((player) => player.bestStreak));
925:   const sorted = [...players].sort((a, b) => b.score - a.score || b.done - a.done || a.name.localeCompare(b.name));
926:   const topScore = sorted.length ? sorted[0].score : 0;
927: 
928:   const categoryTotals = {};
929:   players.forEach((player) => {
930:     Object.entries(player.cats).forEach(([key, value]) => {
931:       categoryTotals[key] = (categoryTotals[key] || 0) + value;
932:     });
933:   });
934:   const topCategory = Object.entries(categoryTotals).sort((a, b) => b[1] - a[1])[0];
935: 
936:   const stats = loadStats();
937:   if (!game.statsRecorded) {
938:     stats.games += 1;
939:     stats.dares += totalDone;
940:     stats.points += totalScore;
941:     stats.bestScore = Math.max(stats.bestScore || 0, topScore);
942:     stats.bestStreak = Math.max(stats.bestStreak || 0, bestStreak);
943:     writeStore(STORAGE_STATS, stats);
944:     game.statsRecorded = true;
945:   }
946: 
947:   els.endKicker.textContent = game.deck.length === 0 ? "DECK COMPLETE" : "RUN COMPLETE";
948: 
949:   if (game.config.mode === "group") {
950:     const tied = sorted.filter((player) => player.score === topScore);
951:     els.endIcon.textContent = "🏆";
952:     if (topScore === 0) {
953:       els.endTitle.textContent = "The Deck Wins";
954:       els.endSubtitle.textContent = "Zero points between you. Bold strategy. The dares remain undefeated.";
955:     } else if (tied.length > 1) {
956:       els.endTitle.textContent = "Dead Heat!";
957:       els.endSubtitle.textContent = `A shared crown at ${topScore} points for ${tied.map((player) => player.name).join(" and ")}. Everyone survives.`;
958:     } else {
959:       els.endTitle.textContent = `${sorted[0].name} Wins!`;
960:       els.endSubtitle.textContent = `${sorted[0].name} banked ${topScore} points. Everyone survives, which is honestly the real win.`;
961:     }
962:   } else {
963:     const ratio = played ? totalDone / played : 0;
964:     const rank = soloRank(ratio, played);
965:     els.endIcon.textContent = rank.icon;
966:     els.endTitle.textContent = rank.title;
967:     els.endSubtitle.textContent = played
968:       ? `${totalDone} of ${played} dares completed for ${totalScore} points. The deck has been notified.`
969:       : "You skipped every card. Technically flawless. Spiritually suspicious.";
970:   }
971: 
972:   els.announcer.textContent = `${els.endTitle.textContent}. ${els.endSubtitle.textContent}`;
973: 
974:   els.endStats.innerHTML = [
975:     { value: `${totalDone}/${played || game.totalTurns}`, label: "Dares done" },
976:     { value: game.config.mode === "group" ? String(topScore) : String(totalScore), label: game.config.mode === "group" ? "Top score" : "Score" },
977:     { value: String(bestStreak), label: "Best streak" },
978:     { value: String(totalChicken + totalSkip), label: "Bailouts" },
979:   ].map((stat) => `<div class="stat"><strong>${stat.value}</strong><span>${stat.label}</span></div>`).join("");
980: 
981:   els.podium.hidden = game.config.mode !== "group";
982:   if (game.config.mode === "group") {
983:     const medals = ["🥇", "🥈", "🥉"];
984:     els.podium.innerHTML = sorted.map((player, index) => `
985:       <div class="podium-row${index === 0 ? " is-winner" : ""}">
986:         <span class="podium-rank" aria-hidden="true">${medals[index] || ordinal(index + 1)}</span>
987:         <span class="podium-name">${esc(player.name)}</span>
988:         <span class="podium-score">${player.done} done · ${player.score} pts</span>
989:       </div>
990:     `).join("");
991:   }
