#fx {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 80;
  pointer-events: none;
  transition: z-index 0s;
}
body.is-end #fx { z-index: 0; }

/* ── Screens ────────────────────────────────────────────────────────── */
.screen {
  position: relative;
  z-index: 1;
  display: none;
  min-height: 100dvh;
}
.screen.is-active {
  display: flex;
  flex-direction: column;
}
.screen.is-entering {
  animation: screenIn 0.45s var(--ease) both;
}

/* ── Header ─────────────────────────────────────────────────────────── */
.site-header {
  position: relative;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  width: min(1240px, 100%);
  margin: 0 auto;
  padding: max(20px, env(safe-area-inset-top)) clamp(18px, 4vw, 40px) 0;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  color: var(--paper);
  text-decoration: none;
  line-height: 1;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
}
h1 span {
  color: var(--acid);
}

.hero-copy {
  max-width: 530px;
  margin: 24px 0 0;
  color: var(--muted);
  font-size: clamp(15px, 1.3vw, 17px);
  line-height: 1.65;
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 24px;
}
.badge {
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.035);
  color: #d9d2e6;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.015em;
}

.safety-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  max-width: 520px;
  margin: 26px 0 0;
  color: var(--muted-2);
  font-size: 12px;
  line-height: 1.55;
}

/* ── Deck fan ───────────────────────────────────────────────────────── */
.deck-fan {
  position: relative;
  width: min(400px, 92%);
  height: 210px;
  margin: 42px 0 0 4px;
}
.fan-card {
  position: absolute;
  left: 12px;
  bottom: 0;
  width: 250px;
  height: 158px;
  padding: 18px;
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  background: linear-gradient(155deg, #241633, #150d21);
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.35);
  transform-origin: 50% 120%;
  transition: transform 0.35s var(--ease);
}
.fan-card span { font-size: 27px; }
.fan-card small {
  position: absolute;
  right: 16px;
  bottom: 14px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.18em;
}
.fan-0 { transform: rotate(-12deg) translate(-13px, 8px); }
.fan-1 { transform: rotate(-5deg) translate(-3px, 2px); }
.fan-2 { transform: rotate(3deg) translate(12px, 0); }
.deck-fan:hover .fan-0 { transform: rotate(-16deg) translate(-22px, 7px); }
.deck-fan:hover .fan-1 { transform: rotate(-7deg) translate(-7px, 2px); }
.deck-fan:hover .fan-2 { transform: rotate(5deg) translate(18px, 0); }
.fan-front {
  width: 276px;
  height: 172px;
  bottom: 12px;
  left: 42px;
  padding: 16px 18px;
  background: linear-gradient(160deg, #fffde1, #f6ff5c 55%, #d9e700);
  color: #100b18;
  border-color: rgba(255, 255, 255, 0.5);
  transform: rotate(-2deg) translateY(-4px);
  box-shadow: 0 24px 54px rgba(0, 0, 0, 0.5), 0 0 50px rgba(246, 255, 92, 0.1);
  display: flex;
  flex-direction: column;
}
.fan-front-top, .fan-front-foot {
  display: flex;
  justify-content: space-between;
  color: rgba(16, 11, 24, 0.68);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.16em;
}
.fan-front strong {
  margin: auto 0;
  font-family: var(--font-display);
  font-size: 21px;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

/* ── Setup panel ────────────────────────────────────────────────────── */
.setup {
  position: relative;
  padding: clamp(20px, 2.6vw, 30px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), transparent 38%),
    var(--panel);
  box-shadow: 0 18px 46px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.setup-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}
.setup-kicker,
.modal-kicker,
.end-kicker {
  margin: 0 0 5px;
  color: var(--acid);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.2em;
}
.setup h2, .modal h2, .end-card h2 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 1;
}
.setup h2 { font-size: 31px; }
.deck-pill {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(0, 0, 0, 0.18);
  line-height: 1.05;
}
.deck-pill strong { color: var(--acid); font-size: 20px; }
.deck-pill span { margin-top: 3px; color: var(--muted-2); font-size: 9px; font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }

.segmented {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(0, 0, 0, 0.22);
}
.mode-switch { margin-bottom: 6px; }
.seg-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 8px 10px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--muted);
  font-size: 13px;
  z-index: 110;
  max-width: min(460px, calc(100vw - 28px));
  padding: 11px 16px;
  border: 1px solid var(--line-strong);
  border-radius: 13px;
  background: rgba(20, 13, 32, 0.95);
  color: var(--paper);
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45);
  font-size: 12px;
  font-weight: 700;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -12px);
  transition: opacity 0.22s, transform 0.22s var(--ease);
}
.toast.is-visible { opacity: 1; transform: translate(-50%, 0); }

/* ── Motion ─────────────────────────────────────────────────────────── */
@keyframes screenIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes dealIn {
  0% { opacity: 0.2; transform: rotateY(72deg) translateY(14px) scale(0.96); }
  70% { opacity: 1; transform: rotateY(-4deg) translateY(0) scale(1.003); }
  100% { opacity: 1; transform: rotateY(0) translateY(0) scale(1); }
}
@keyframes stampIn {
  from { opacity: 0; transform: scale(0.94); }
  to { opacity: 1; transform: scale(1); }
}
@keyframes scorePop {
  0% { transform: scale(1); }
  45% { transform: scale(1.16); }
  100% { transform: scale(1); }
}
@keyframes modalIn {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}
@keyframes urgent {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.35; }
}

/* ── Responsive ─────────────────────────────────────────────────────── */
@media (max-width: 940px) {
  .home-main {
