import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

process.env.DISPLAY ||= ':' + readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/display'), 'utf8').trim()
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
const results = []
const check = (name, ok, detail = '') => { results.push({ name, ok, detail }); console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ' — ' + detail : ''}`) }

const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (error) => errors.push(`pageerror: ${error.message}`))
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`) })
page.on('response', (res) => { if (res.status() >= 400) errors.push(`http ${res.status()}: ${res.url()}`) })

await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.waitForTimeout(300)
check('home visible', await page.locator('#screen-home').isVisible())
check('library count 132', (await page.locator('#library-count').textContent()).includes('132'))
check('start enabled', await page.locator('#start-game').isEnabled())

// Gather home overflow info
for (const [w, h] of [[1440, 900], [1280, 720], [390, 844], [375, 667], [320, 568], [768, 1024]]) {
  await page.setViewportSize({ width: w, height: h })
  await page.waitForTimeout(80)
  const dims = await page.evaluate(() => ({ scrollW: document.documentElement.scrollWidth, innerW: innerWidth, scrollH: document.documentElement.scrollHeight, innerH: innerHeight, cx: document.querySelector('#start-game').getBoundingClientRect().toJSON() }))
  check(`home no horizontal overflow ${w}x${h}`, dims.scrollW <= dims.innerW + 1, `scrollW=${dims.scrollW} innerW=${dims.innerW}`)
  check(`home start visible ${w}x${h}`, dims.cx.top < dims.innerH && dims.cx.bottom > 0, `top=${Math.round(dims.cx.top)} bottom=${Math.round(dims.cx.bottom)}`)
}

await page.setViewportSize({ width: 1440, height: 900 })
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.waitForTimeout(200)

// Solo 5 run, timer test
await page.locator('[data-length="5"]').click()
await page.locator('#start-game').click()
await page.waitForTimeout(650)
check('solo game visible', await page.locator('#screen-game').isVisible())
check('progress 1 of 5', (await page.locator('#progress-label').textContent()).includes('1 of 5'))
const firstId = await page.evaluate(() => window.__dareDeck.game.currentDare.id)
const firstSecs = await page.evaluate(() => window.__dareDeck.game.currentDare.secs)
check('first dare assigned', Boolean(firstId), firstId)

if (firstSecs > 0) {
  await page.locator('[data-action="timer"]').click()
  await page.waitForTimeout(500)
  check('timer running', await page.evaluate(() => window.__dareDeck.game.phase === 'running'))
  await page.locator('[data-action="timer"]').click()
  check('timer paused', await page.evaluate(() => window.__dareDeck.game.phase === 'paused'))
  await page.waitForTimeout(300)
  const pausedAt = await page.evaluate(() => window.__dareDeck.game.timer.remaining)
  await page.waitForTimeout(300)
  const stillPaused = await page.evaluate(() => window.__dareDeck.game.timer.remaining)
  check('pause freezes timer', Math.abs(pausedAt - stillPaused) < 0.05, `${pausedAt.toFixed(2)} vs ${stillPaused.toFixed(2)}`)
  await page.locator('[data-action="timer"]').click()
  await page.waitForTimeout(300)
  check('timer resumed', await page.evaluate(() => window.__dareDeck.game.phase === 'running'))
}

const firstScore = await page.evaluate(() => window.__dareDeck.game.players[0].score)
await page.locator('[data-action="done"]').click()
await page.waitForTimeout(300)
check('result stamp shown', await page.locator('#result-stamp').isVisible())
check('score increased', await page.evaluate((s) => window.__dareDeck.game.players[0].score > s, firstScore))
check('no repeat current draw', await page.evaluate((id) => window.__dareDeck.game.deck.every((d) => d.id !== id), firstId))

// Finish run, alternating done / chicken / skip
for (let i = 0; i < 10; i++) {
  const state = await page.evaluate(() => ({ finished: window.__dareDeck.game?.finished, phase: window.__dareDeck.game?.phase }))
  if (state.finished) break
  if (state.phase === 'result') {
    await page.locator('[data-action="next"]').click()
  } else {
    const action = i % 3 === 0 ? 'done' : i % 3 === 1 ? 'chicken' : 'skip'
    await page.locator(`[data-action="${action}"]`).click()
    await page.waitForTimeout(40)
    await page.locator('[data-action="next"]').click()
  }
  await page.waitForTimeout(80)
}
check('solo run ended', await page.locator('#screen-end').isVisible())
check('end title present', ((await page.locator('#end-title').textContent()) || '').trim().length > 0)
check('end stats present', (await page.locator('#end-stats .stat').count()) === 4)
check('lifetime present', (await page.locator('#lifetime').textContent()).includes('Lifetime'))
const drawnCount = await page.evaluate(() => window.__dareDeck.game.drawn)
check('run drew exactly 5', drawnCount === 5, `drawn=${drawnCount}`)

// Play again resets cleanly
await page.locator('#play-again').click()
await page.waitForTimeout(300)
check('play again starts fresh', await page.evaluate(() => window.__dareDeck.game.turn === 1 && window.__dareDeck.game.players[0].score === 0 && window.__dareDeck.game.drawn === 1))

// Quit dialog
await page.locator('#quit-game').click()
await page.waitForTimeout(200)
check('quit dialog opens', await page.locator('#quit-dialog').evaluate((d) => d.open))
await page.locator('#quit-dialog button[value="quit"]').click()
await page.waitForTimeout(300)
check('quit returns home', await page.locator('#screen-home').isVisible())

// Group mode
await page.locator('[data-mode="group"]').click()
await page.locator('#player-input').fill('Maya')
await page.locator('#add-player').click()
await page.locator('#player-input').fill('Theo')
await page.locator('#add-player').click()
check('four players', (await page.locator('.player-row').count()) === 4)
await page.locator('[data-length="5"]') // ensure no-op
await page.locator('#start-game').click()
await page.waitForTimeout(650)
check('group game visible', await page.locator('#screen-game').isVisible())
check('players strip visible', await page.locator('#players-strip').isVisible())
const firstName = await page.locator('#turn-label').textContent()
check('group shows player name', !firstName.toLowerCase().includes('dare'), firstName)
check('turn order starts at 0', await page.evaluate(() => window.__dareDeck.game.activeIndex === 0))
await page.locator('[data-action="skip"]').click()
await page.locator('[data-action="next"]').click()
await page.waitForTimeout(150)
check('turn passed to player 2', await page.evaluate(() => window.__dareDeck.game.activeIndex === 1))
const chipActive = await page.locator('#players-strip .player-chip.is-active').count()
check('active chip updates', chipActive === 1)

// Finish group run
for (let i = 0; i < 30; i++) {
  const state = await page.evaluate(() => ({ finished: window.__dareDeck.game?.finished, phase: window.__dareDeck.game?.phase }))
  if (state.finished) break
  if (state.phase === 'result') await page.locator('[data-action="next"]').click()
  else { await page.locator('[data-action="done"]').click(); await page.locator('[data-action="next"]').click() }
  await page.waitForTimeout(60)
}
check('group run ended', await page.locator('#screen-end').isVisible())
check('podium shown', await page.locator('#podium').isVisible())
check('podium has 4 rows', (await page.locator('.podium-row').count()) === 4)

// Mobile gameplay fit
await page.locator('#change-setup').click()
await page.waitForTimeout(250)
await page.locator('[data-mode="solo"]').click()
await page.locator('[data-length="5"]').click()
for (const [w, h] of [[390, 844], [375, 667], [320, 568]]) {
  await page.setViewportSize({ width: w, height: h })
  await page.locator('#start-game').click()
  await page.waitForTimeout(650)
  const fit = await page.evaluate(() => {
    const rect = document.querySelector('[data-action="skip"]')?.getBoundingClientRect()
    return { screen: document.querySelector('.screen.is-active')?.id, scrollW: document.documentElement.scrollWidth, innerW: innerWidth, bottom: rect ? rect.bottom : null, innerH: innerHeight }
  })
  check(`mobile controls fit ${w}x${h}`, fit.screen === 'screen-game' && fit.scrollW <= fit.innerW + 1 && fit.bottom !== null && fit.bottom <= fit.innerH + 1, `bottom=${fit.bottom && Math.round(fit.bottom)} innerH=${fit.innerH} scrollW=${fit.scrollW}`)
  await page.locator('#quit-game').click()
  await page.waitForTimeout(120)
  await page.locator('#quit-dialog button[value="quit"]').click()
  await page.waitForTimeout(220)
}

// Rules dialog
await page.locator('#rules-button').click()
await page.waitForTimeout(120)
check('rules dialog opens', await page.locator('#rules-dialog').evaluate((d) => d.open))
check('rules has six rules', (await page.locator('#rules-dialog .rule').count()) === 6)
await page.locator('#rules-dialog .modal-close').click()
await page.waitForTimeout(120)

check('no page/console/network errors', errors.length === 0, errors.slice(0, 4).join(' | '))

await browser.close()
const failed = results.filter((r) => !r.ok)
console.log(`\n${results.length - failed.length}/${results.length} checks passed.`)
process.exit(failed.length ? 1 : 0)

