import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
process.env.DISPLAY ||= ':' + readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/display'), 'utf8').trim()
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
for (const [w, h, name] of [[390, 844, 'home-mobile'], [1440, 900, 'home-desktop']]) {
  const page = await browser.newPage({ viewport: { width: w, height: h }, hasTouch: w < 700, isMobile: w < 700 })
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  await page.waitForTimeout(400)
  await page.screenshot({ path: `/tmp/opencode/${name}.png`, fullPage: false })
  await page.screenshot({ path: `/tmp/opencode/${name}-full.png`, fullPage: true })
  console.log(name, await page.evaluate(() => ({ scrollH: document.documentElement.scrollHeight, innerH: innerHeight })))
  await page.close()
}
await browser.close()

