input.content:
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
process.env.DISPLAY ||= ':' + readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/display'), 'utf8').trim()
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 900, height: 800 } })
const errors = []
page.on('pageerror', (e) => errors.push(e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
const result = await page.evaluate(() => {
  const api = window.__dareDeck
  api.startGame({ mode: 'solo', length: 10, turns: 1, level: 1, categories: ['taste'], players: [{ name: 'You' }] })
  const ids = []
  for (let i = 0; i < 20; i++) {
    const g = api.game
    if (!g || g.finished) break
    if (g.phase === 'result') document.querySelector('[data-action="next"]')?.click()
    else {
      ids.push(g.currentDare.id)
      document.querySelector('[data-action="done"]')?.click()
      document.querySelector('[data-action="next"]')?.click()
    }
  }
  return { ids, finished: api.game?.finished, total: api.game?.totalTurns, drawn: api.game?.drawn, screen: document.querySelector('.screen.is-active')?.id }
})
console.log(result)
console.log('unique', new Set(result.ids).size, 'errors', errors)
await page.waitForTimeout(400)
console.log('end title', await page.locator('#end-title').textContent(), '| lifetime', await page.locator('#lifetime').textContent())
await browser.close()

